+// Sales from the till: each dish sold uses one portion of its recipe per
+// unit of `qty`. A ticket is booked once; booking a file is all or nothing.
+import { AppError } from "../errors.js";
+import { consume } from "./batches.js";
+import { getItem, onHand } from "./items.js";
+import { getDish } from "./menu.js";
+import { getRecipe, scaled } from "./recipes.js";
+
+const round3 = (n) => Math.round(n * 1000) / 1000;
+
+/** True when a ticket's sales were already booked. */
+export function ticketBooked(store, ticket) {
+  return (store.data.sales ?? []).some((s) => s.ticket === ticket);
+}
+
+/**
+ * Books sale lines { row, ticket, soldAt, dishId, qty } (`row` names the line
+ * in errors). Lines of tickets already booked are skipped. Checks stock for
+ * every line first; throws not_enough_stock_row and changes nothing when an
+ * item runs out. Returns { tickets, dishes } booked.
+ */
+export function bookSales(store, lines) {
+  const fresh = lines
+    .filter((l) => !ticketBooked(store, l.ticket))
+    .map((l) => {
+      const dish = getDish(store, l.dishId);
+      const recipe = getRecipe(store, dish.recipeId);
+      return { ...l, recipeId: recipe.id, uses: scaled(recipe, l.qty).filter((u) => u.qty > 0) };
+    });
+  const left = new Map();
+  for (const l of fresh) {
+    for (const u of l.uses) {
+      if (!left.has(u.itemId)) left.set(u.itemId, round3(onHand(store, u.itemId)));
+      const after = round3(left.get(u.itemId) - u.qty);
+      if (after < 0) {
+        const item = getItem(store, u.itemId);
+        throw new AppError("not_enough_stock_row", { row: l.row, item: item.name, available: left.get(u.itemId), unit: item.unit });
+      }
+      left.set(u.itemId, after);
+    }
+  }
+  store.data.sales ??= [];
+  for (const l of fresh) {
+    for (const u of l.uses) consume(store, u.itemId, u.qty, { at: l.soldAt, ref: `sale:${l.ticket}` });
+    store.data.sales.push({ id: store.nextId("sale"), ticket: l.ticket, soldAt: l.soldAt, dishId: l.dishId, recipeId: l.recipeId, qty: l.qty, uses: l.uses });
+  }
+  return { tickets: new Set(fresh.map((l) => l.ticket)).size, dishes: fresh.reduce((s, l) => s + l.qty, 0) };
+}
+
+/**
+ * Variance per item between two days (inclusive): theoretical use from sales
+ * sold in those days, actual use from every consume movement, and the
+ * difference (actual - theoretical). Only items where either is above zero.
+ */
+export function varianceReport(store, from, to) {
+  const inRange = (at) => {
+    const day = at.slice(0, 10);
+    return day >= from && day <= to;
+  };
+  const lines = new Map();
+  const line = (itemId) => {
+    if (!lines.has(itemId)) lines.set(itemId, { theoretical: 0, actual: 0 });
+    return lines.get(itemId);
+  };
+  for (const s of store.data.sales ?? []) {
+    if (!inRange(s.soldAt)) continue;
+    for (const u of s.uses) line(u.itemId).theoretical += u.qty;
+  }
+  const batchItem = new Map(store.data.batches.map((b) => [b.id, b.itemId]));
+  for (const m of store.data.movements) {
+    if (m.type !== "consume" || !inRange(m.at)) continue;
+    const itemId = batchItem.get(m.batchId);
+    if (itemId === undefined) continue;
+    line(itemId).actual += m.qty;
+  }
+  return [...lines]
+    .map(([itemId, l]) => {
+      const theoretical = round3(l.theoretical);
+      const actual = round3(l.actual);
+      const item = store.data.items.find((i) => i.id === itemId);
+      return { itemId, name: item?.name ?? null, unit: item?.unit ?? null, theoretical, actual, difference: round3(actual - theoretical) };
+    })
+    .filter((l) => l.theoretical > 0 || l.actual > 0)
+    .sort((a, b) => a.itemId - b.itemId);
+}
